const projectDefault=(lon,lat)=>({x:(lon+.278)*LON,z:(39.679-lat)*111320});
export const berenguerPeriods=[{id:'house',label:'La casa y sus transformaciones',color:'#d7b36b'},{id:'courtyards',label:'Patios, galerías y desniveles',color:'#b6c593'},{id:'water',label:'El aljibe y la bóveda',color:'#7fb7c4'},{id:'wall',label:'La fábrica del muro de Diana',color:'#c99bba'},{id:'context',label:'Conservación y entorno',color:'#80aa85'}];
