function irregularBlock(b,k,f,u,y,w,h,z,depth,seed){const inset=.024,face=[[-w/2+inset,-h/2+inset],[-w/2+w*.18,-h/2+inset*(1+noise(seed))],[w/2-inset,-h/2+.025+noise(seed+2)*.055],[w/2-inset,h/2-.03],[-w/2+w*.08,h/2-inset],[-w/2+inset,h*.10]],p=[];const front=face.map(([x,yy])=>f.p(u+x,y+yy,z-depth/2-(noise(seed+13+x)*.055))),back=face.map(([x,yy])=>f.p(u+x,y+yy,z+depth/2));for(let i=1;i<face.length-1;i++){p.push(...front[0],...front[i],...front[i+1]);p.push(...back[0],...back[i+1],...back[i]);}for(let i=0;i<face.length;i++)quad(p,front[i],front[(i+1)%face.length],back[(i+1)%face.length],back[i]);b.raw(k,p,.82+noise(seed)*.30);}
